import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import '../services/services.dart';
class ConnectPage extends StatelessWidget{const ConnectPage({super.key});String cid(String a,String b)=>a.compareTo(b)<0?'$a-$b':'$b-$a';@override Widget build(BuildContext c){final me=FirebaseAuth.instance.currentUser!;return Scaffold(backgroundColor:Colors.transparent,body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').limit(50).snapshots(),builder:(c,s){final users=(s.data?.docs??[]).where((x)=>x.id!=me.uid).toList();return CustomScrollView(slivers:[const SliverAppBar(backgroundColor:Colors.transparent,floating:true,title:Text('Connect',style:TextStyle(fontWeight:FontWeight.w900,fontSize:26))),SliverPadding(padding:const EdgeInsets.all(12),sliver:SliverList.builder(itemCount:users.length,itemBuilder:(c,i){final u=users[i],a=u.data();return Card(child:ListTile(leading:CircleAvatar(child:Text((a['name']??'U').toString().characters.first.toUpperCase())),title:Text(a['name']??'WATCHKEEPER user',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(a['email']??''),trailing:const Icon(Icons.chat_bubble_outline),onTap:()async{final id=cid(me.uid,u.id);await DB.conversations.doc(id).set({'members':[me.uid,u.id],'memberNames':{me.uid:me.displayName??me.email,u.id:a['name']??a['email']},'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));if(c.mounted)Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatPage(id:id,title:a['name']??'Chat')));});}))]);}));}}
class ChatPage extends StatefulWidget{const ChatPage({super.key,required this.id,required this.title});final String id,title;@override State<ChatPage> createState()=>_Chat();}
class _Chat extends State<ChatPage>{final t=TextEditingController();Future<void> send()async{final q=t.text.trim();if(q.isEmpty)return;t.clear();final r=DB.conversations.doc(widget.id);await r.collection('messages').add({'senderId':DB.uid,'text':q,'at':FieldValue.serverTimestamp(),'type':'text'});await r.update({'lastMessage':q,'updatedAt':FieldValue.serverTimestamp()});}@override Widget build(BuildContext c){final r=DB.conversations.doc(widget.id);return Scaffold(appBar:AppBar(title:Text(widget.title)),body:Column(children:[Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:r.collection('messages').orderBy('at',descending:true).limit(100).snapshots(),builder:(c,s){final d=s.data?.docs??[];return ListView.builder(reverse:true,padding:const EdgeInsets.all(14),itemCount:d.length,itemBuilder:(c,i){final a=d[i].data(),mine=a['senderId']==DB.uid;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.symmetric(vertical:4),padding:const EdgeInsets.symmetric(horizontal:15,vertical:11),constraints:BoxConstraints(maxWidth:MediaQuery.sizeOf(c).width*.78),decoration:BoxDecoration(color:mine?Theme.of(c).colorScheme.primary:Colors.white10,borderRadius:BorderRadius.circular(20)),child:Text(a['text']??'')));});})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:t,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Message…'))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send_rounded))]))) ]));}}
